/** Rust-owned contracts generated by Bindings::write_contracts. */
export interface CapabilityContract {
  readonly name: string;
  readonly version: number;
  readonly methods: readonly {
    readonly name: string;
    readonly hasRequest: boolean;
    readonly json: boolean;
  }[];
}
export interface RustCapabilityOptions {
  contract: CapabilityContract;
  manifest: string;
  watch?: string[];
  features?: string[];
  targetDirectory?: string;
}
export interface RuntimeCapability extends CapabilityContract {
  implementation: {
    kind: "project";
    manifest: string;
    watch: string[];
    features: string[];
    targetDirectory?: string;
  };
}
/** Select an implementation for a generated contract without repeating its methods. */
export function rustCapability({
  contract,
  manifest,
  watch = [],
  features = [],
  targetDirectory,
}: RustCapabilityOptions): RuntimeCapability {
  return {
    ...contract,
    implementation: {
      kind: "project",
      manifest,
      watch,
      features,
      ...(targetDirectory ? { targetDirectory } : {}),
    },
  };
}
export interface WabouProjectConfig {
  window?: {
    title?: string;
    width?: number;
    height?: number;
    decorations?: boolean;
  };
  ui?: { entry?: string };
  capabilities?: RuntimeCapability[];
}
/** Type-check ordinary data or an asynchronous environment-dependent factory. */
export function defineConfig<
  T extends
    | WabouProjectConfig
    | (() => WabouProjectConfig | Promise<WabouProjectConfig>),
>(config: T): T {
  return config;
}
